<link rel="stylesheet" href="assets/asset-register.css"><section class="page-heading"><div><span class="section-label">ASSET <?php echo propertyPortalEscape((string)$asset['asset_code']);?></span><h1><?php echo propertyPortalEscape((string)$asset['asset_name']);?></h1><p><?php echo propertyPortalEscape((string)$asset['asset_category']);?> · <?php echo propertyPortalEscape((string)$asset['location']);?></p></div><div class="asset-actions"><a class="button button-primary" href="asset_edit.php?id=<?php echo $id;?>">Edit Asset</a><a class="button button-secondary" href="asset_qr.php?id=<?php echo $id;?>">QR Code</a><a class="button button-secondary" href="assets.php">Back</a></div></section><section class="asset-detail-grid"><div class="panel"><?php if(!empty($asset['photo_path'])):?><img class="asset-photo" src="<?php echo propertyPortalEscape((string)$asset['photo_path']);?>" alt="Asset photo"><?php endif;?><div class="detail-grid"><?php foreach(['asset_code'=>'Asset ID','condition_rating'=>'Condition','asset_status'=>'Status','brand'=>'Brand','model'=>'Model','serial_number'=>'Serial No.','purchase_date'=>'Purchase Date','purchase_cost'=>'Purchase Cost','installation_date'=>'Installation Date','warranty_expiry'=>'Warranty Expiry','maintenance_frequency'=>'PM Frequency','next_service_date'=>'Next Service'] as $k=>$l):?><div><span><?php echo $l;?></span><strong><?php echo propertyPortalEscape((string)($asset[$k]?:'-'));?></strong></div><?php endforeach;?></div></div><div class="panel"><h2>Inspection History</h2><?php foreach($ins as $x):?><div class="history-row"><a href="inspection_view.php?id=<?php echo (int)$x['id'];?>"><strong><?php echo propertyPortalEscape((string)$x['inspection_no']);?></strong></a><span><?php echo propertyPortalEscape((string)$x['inspection_date']);?> · <?php echo propertyPortalEscape((string)$x['status']);?></span></div><?php endforeach;?><?php if(!$ins):?><p>No linked inspections yet.</p><?php endif;?><h2>Asset Timeline</h2><?php foreach($history as $x):?><div class="history-row"><strong><?php echo propertyPortalEscape((string)$x['event_type']);?></strong><span><?php echo propertyPortalEscape((string)$x['created_at']);?> · <?php echo propertyPortalEscape((string)$x['changed_by']);?></span><p><?php echo propertyPortalEscape((string)$x['event_notes']);?></p></div><?php endforeach;?></div></section><?php require __DIR__.'/includes/layout_footer.php';?>
